window.__code__["code-w08-rag-two-modes-py"] = {"code_id": "code-w08-rag-two-modes-py", "kind": "local", "title": "rag_two_modes.py", "source_path": "/Users/zhongyou/Desktop/2027年/code/w08/rag_two_modes.py", "highlight_line": null, "code_html": "<div class=\"code-body\">\n<div class=\"c-line\" data-line=\"1\"><span class=\"c-no\">1</span><span class=\"c-src\"><span class=\"c-com\"># code/w08/rag_two_modes.py</span></span></div>\n<div class=\"c-line\" data-line=\"2\"><span class=\"c-no\">2</span><span class=\"c-src\"><span class=\"c-com\"># ============================================================</span></span></div>\n<div class=\"c-line\" data-line=\"3\"><span class=\"c-no\">3</span><span class=\"c-src\"><span class=\"c-com\"># W08 作业1:建知识库做 RAG,对比 static(自动注入)与 agentic(主动搜索)两种模式</span></span></div>\n<div class=\"c-line\" data-line=\"4\"><span class=\"c-no\">4</span><span class=\"c-src\"><span class=\"c-com\"># 对照官方示例:examples/rag/integrate_with_agent.py</span></span></div>\n<div class=\"c-line\" data-line=\"5\"><span class=\"c-no\">5</span><span class=\"c-src\"><span class=\"c-com\"># 前置: export DASHSCOPE_API_KEY=\u00004\u0000</span></span></div>\n<div class=\"c-line\" data-line=\"6\"><span class=\"c-no\">6</span><span class=\"c-src\"><span class=\"c-com\"># 运行:  python code/w08/rag_two_modes.py</span></span></div>\n<div class=\"c-line\" data-line=\"7\"><span class=\"c-no\">7</span><span class=\"c-src\"><span class=\"c-com\"># 预期:</span></span></div>\n<div class=\"c-line\" data-line=\"8\"><span class=\"c-no\">8</span><span class=\"c-src\"><span class=\"c-com\">#   - 索引一段 FAQ 文本到向量库(Qdrant 内存版,零外部依赖)</span></span></div>\n<div class=\"c-line\" data-line=\"9\"><span class=\"c-no\">9</span><span class=\"c-src\"><span class=\"c-com\">#   - static 模式:自动检索用 HintBlock 注入,Agent 据此答</span></span></div>\n<div class=\"c-line\" data-line=\"10\"><span class=\"c-no\">10</span><span class=\"c-src\"><span class=\"c-com\">#   - agentic 模式:Agent 主动调 search_knowledge 工具检索再答</span></span></div>\n<div class=\"c-line\" data-line=\"11\"><span class=\"c-no\">11</span><span class=\"c-src\"><span class=\"c-com\"># ============================================================</span></span></div>\n<div class=\"c-line\" data-line=\"12\"><span class=\"c-no\">12</span><span class=\"c-src\"><span class=\"c-kw\">import</span> asyncio</span></div>\n<div class=\"c-line\" data-line=\"13\"><span class=\"c-no\">13</span><span class=\"c-src\"><span class=\"c-kw\">import</span> os</span></div>\n<div class=\"c-line\" data-line=\"14\"><span class=\"c-no\">14</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"15\"><span class=\"c-no\">15</span><span class=\"c-src\"><span class=\"c-kw\">from</span> agentscope.agent <span class=\"c-kw\">import</span> Agent</span></div>\n<div class=\"c-line\" data-line=\"16\"><span class=\"c-no\">16</span><span class=\"c-src\"><span class=\"c-kw\">from</span> agentscope.credential <span class=\"c-kw\">import</span> DashScopeCredential</span></div>\n<div class=\"c-line\" data-line=\"17\"><span class=\"c-no\">17</span><span class=\"c-src\"><span class=\"c-kw\">from</span> agentscope.embedding <span class=\"c-kw\">import</span> DashScopeEmbeddingModel</span></div>\n<div class=\"c-line\" data-line=\"18\"><span class=\"c-no\">18</span><span class=\"c-src\"><span class=\"c-kw\">from</span> agentscope.message <span class=\"c-kw\">import</span> UserMsg</span></div>\n<div class=\"c-line\" data-line=\"19\"><span class=\"c-no\">19</span><span class=\"c-src\"><span class=\"c-kw\">from</span> agentscope.middleware <span class=\"c-kw\">import</span> RAGMiddleware</span></div>\n<div class=\"c-line\" data-line=\"20\"><span class=\"c-no\">20</span><span class=\"c-src\"><span class=\"c-kw\">from</span> agentscope.model <span class=\"c-kw\">import</span> DashScopeChatModel</span></div>\n<div class=\"c-line\" data-line=\"21\"><span class=\"c-no\">21</span><span class=\"c-src\"><span class=\"c-kw\">from</span> agentscope.rag <span class=\"c-kw\">import</span> (</span></div>\n<div class=\"c-line\" data-line=\"22\"><span class=\"c-no\">22</span><span class=\"c-src\">    ApproxTokenChunker,</span></div>\n<div class=\"c-line\" data-line=\"23\"><span class=\"c-no\">23</span><span class=\"c-src\">    KnowledgeBase,</span></div>\n<div class=\"c-line\" data-line=\"24\"><span class=\"c-no\">24</span><span class=\"c-src\">    QdrantStore,</span></div>\n<div class=\"c-line\" data-line=\"25\"><span class=\"c-no\">25</span><span class=\"c-src\">    TextParser,</span></div>\n<div class=\"c-line\" data-line=\"26\"><span class=\"c-no\">26</span><span class=\"c-src\">)</span></div>\n<div class=\"c-line\" data-line=\"27\"><span class=\"c-no\">27</span><span class=\"c-src\"><span class=\"c-kw\">from</span> agentscope.tool <span class=\"c-kw\">import</span> Toolkit</span></div>\n<div class=\"c-line\" data-line=\"28\"><span class=\"c-no\">28</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"29\"><span class=\"c-no\">29</span><span class=\"c-src\"><span class=\"c-com\"># 一段假 FAQ 文档(模型自带知识里没有的\u000012\u0000,验证它确实在用 RAG)</span></span></div>\n<div class=\"c-line\" data-line=\"30\"><span class=\"c-no\">30</span><span class=\"c-src\">FAQ = b<span class=\"c-str\">&quot;&quot;</span>&quot;小白公司退货政策:</span></div>\n<div class=\"c-line\" data-line=\"31\"><span class=\"c-no\">31</span><span class=\"c-src\">- 7天内未拆封商品可全额退款。</span></div>\n<div class=\"c-line\" data-line=\"32\"><span class=\"c-no\">32</span><span class=\"c-src\">- 拆封商品需扣 20% 折旧费。</span></div>\n<div class=\"c-line\" data-line=\"33\"><span class=\"c-no\">33</span><span class=\"c-src\">- 食品类商品一经售出不退换。</span></div>\n<div class=\"c-line\" data-line=\"34\"><span class=\"c-no\">34</span><span class=\"c-src\">- 退款到原支付账户,3-5 工作日到账。</span></div>\n<div class=\"c-line\" data-line=\"35\"><span class=\"c-no\">35</span><span class=\"c-src\"><span class=\"c-str\">&quot;&quot;</span>&quot;</span></div>\n<div class=\"c-line\" data-line=\"36\"><span class=\"c-no\">36</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"37\"><span class=\"c-no\">37</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"38\"><span class=\"c-no\">38</span><span class=\"c-src\"><span class=\"c-kw\">async</span> <span class=\"c-kw\">def</span> build_kb() -&gt; KnowledgeBase:</span></div>\n<div class=\"c-line\" data-line=\"39\"><span class=\"c-no\">39</span><span class=\"c-src\">    <span class=\"c-com\"># 注意:dimensions 是 __init__ 的第 3 个必填位置参数(契约层 required)</span></span></div>\n<div class=\"c-line\" data-line=\"40\"><span class=\"c-no\">40</span><span class=\"c-src\">    <span class=\"c-com\"># text-embedding-v4 支持 1024/768 等,这里用 1024</span></span></div>\n<div class=\"c-line\" data-line=\"41\"><span class=\"c-no\">41</span><span class=\"c-src\">    embedding = DashScopeEmbeddingModel(</span></div>\n<div class=\"c-line\" data-line=\"42\"><span class=\"c-no\">42</span><span class=\"c-src\">        credential=DashScopeCredential(api_key=os.environ[<span class=\"c-str\">&quot;DASHSCOPE_API_KEY&quot;</span>]),</span></div>\n<div class=\"c-line\" data-line=\"43\"><span class=\"c-no\">43</span><span class=\"c-src\">        model=<span class=\"c-str\">&quot;text-embedding-v4&quot;</span>,</span></div>\n<div class=\"c-line\" data-line=\"44\"><span class=\"c-no\">44</span><span class=\"c-src\">        dimensions=1024,</span></div>\n<div class=\"c-line\" data-line=\"45\"><span class=\"c-no\">45</span><span class=\"c-src\">    )</span></div>\n<div class=\"c-line\" data-line=\"46\"><span class=\"c-no\">46</span><span class=\"c-src\">    kb = KnowledgeBase(</span></div>\n<div class=\"c-line\" data-line=\"47\"><span class=\"c-no\">47</span><span class=\"c-src\">        name=<span class=\"c-str\">&quot;faq&quot;</span>,</span></div>\n<div class=\"c-line\" data-line=\"48\"><span class=\"c-no\">48</span><span class=\"c-src\">        description=<span class=\"c-str\">&quot;小白公司退货政策FAQ&quot;</span>,</span></div>\n<div class=\"c-line\" data-line=\"49\"><span class=\"c-no\">49</span><span class=\"c-src\">        embedding_model=embedding,</span></div>\n<div class=\"c-line\" data-line=\"50\"><span class=\"c-no\">50</span><span class=\"c-src\">        vector_store=QdrantStore(location=<span class=\"c-str\">&quot;:memory:&quot;</span>),  <span class=\"c-com\"># 内存版,零依赖</span></span></div>\n<div class=\"c-line\" data-line=\"51\"><span class=\"c-no\">51</span><span class=\"c-src\">        collection=<span class=\"c-str\">&quot;faq&quot;</span>,</span></div>\n<div class=\"c-line\" data-line=\"52\"><span class=\"c-no\">52</span><span class=\"c-src\">    )</span></div>\n<div class=\"c-line\" data-line=\"53\"><span class=\"c-no\">53</span><span class=\"c-src\">    <span class=\"c-com\"># 解析 -&gt; 分块 -&gt; 入库</span></span></div>\n<div class=\"c-line\" data-line=\"54\"><span class=\"c-no\">54</span><span class=\"c-src\">    parser = TextParser()</span></div>\n<div class=\"c-line\" data-line=\"55\"><span class=\"c-no\">55</span><span class=\"c-src\">    chunker = ApproxTokenChunker(chunk_size=128, overlap=32)</span></div>\n<div class=\"c-line\" data-line=\"56\"><span class=\"c-no\">56</span><span class=\"c-src\">    sections = <span class=\"c-kw\">await</span> parser.parse(file=FAQ, filename=<span class=\"c-str\">&quot;refund_policy.txt&quot;</span>)</span></div>\n<div class=\"c-line\" data-line=\"57\"><span class=\"c-no\">57</span><span class=\"c-src\">    chunks = <span class=\"c-kw\">await</span> chunker.chunk(sections)</span></div>\n<div class=\"c-line\" data-line=\"58\"><span class=\"c-no\">58</span><span class=\"c-src\">    <span class=\"c-kw\">await</span> kb.insert_document(chunks)</span></div>\n<div class=\"c-line\" data-line=\"59\"><span class=\"c-no\">59</span><span class=\"c-src\">    <span class=\"c-kw\">return</span> kb</span></div>\n<div class=\"c-line\" data-line=\"60\"><span class=\"c-no\">60</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"61\"><span class=\"c-no\">61</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"62\"><span class=\"c-no\">62</span><span class=\"c-src\"><span class=\"c-kw\">def</span> make_model() -&gt; DashScopeChatModel:</span></div>\n<div class=\"c-line\" data-line=\"63\"><span class=\"c-no\">63</span><span class=\"c-src\">    <span class=\"c-kw\">return</span> DashScopeChatModel(</span></div>\n<div class=\"c-line\" data-line=\"64\"><span class=\"c-no\">64</span><span class=\"c-src\">        credential=DashScopeCredential(api_key=os.environ[<span class=\"c-str\">&quot;DASHSCOPE_API_KEY&quot;</span>]),</span></div>\n<div class=\"c-line\" data-line=\"65\"><span class=\"c-no\">65</span><span class=\"c-src\">        model=<span class=\"c-str\">&quot;qwen-plus&quot;</span>,</span></div>\n<div class=\"c-line\" data-line=\"66\"><span class=\"c-no\">66</span><span class=\"c-src\">        stream=<span class=\"c-kw\">True</span>,</span></div>\n<div class=\"c-line\" data-line=\"67\"><span class=\"c-no\">67</span><span class=\"c-src\">    )</span></div>\n<div class=\"c-line\" data-line=\"68\"><span class=\"c-no\">68</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"69\"><span class=\"c-no\">69</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"70\"><span class=\"c-no\">70</span><span class=\"c-src\"><span class=\"c-kw\">async</span> <span class=\"c-kw\">def</span> run(agent: Agent, query: str, tag: str) -&gt; <span class=\"c-kw\">None</span>:</span></div>\n<div class=\"c-line\" data-line=\"71\"><span class=\"c-no\">71</span><span class=\"c-src\">    print(f<span class=\"c-str\">&quot;\\n=== {tag} ===&quot;</span>)</span></div>\n<div class=\"c-line\" data-line=\"72\"><span class=\"c-no\">72</span><span class=\"c-src\">    print(f<span class=\"c-str\">&quot;👤 {query}&quot;</span>)</span></div>\n<div class=\"c-line\" data-line=\"73\"><span class=\"c-no\">73</span><span class=\"c-src\">    print(<span class=\"c-str\">&quot;🤖 &quot;</span>, end=<span class=\"c-str\">&quot;&quot;</span>)</span></div>\n<div class=\"c-line\" data-line=\"74\"><span class=\"c-no\">74</span><span class=\"c-src\">    <span class=\"c-kw\">async</span> <span class=\"c-kw\">for</span> e <span class=\"c-kw\">in</span> agent.reply_stream(UserMsg(<span class=\"c-str\">&quot;u&quot;</span>, query)):</span></div>\n<div class=\"c-line\" data-line=\"75\"><span class=\"c-no\">75</span><span class=\"c-src\">        <span class=\"c-kw\">if</span> e.type.value == <span class=\"c-str\">&quot;TEXT_BLOCK_DELTA&quot;</span>:</span></div>\n<div class=\"c-line\" data-line=\"76\"><span class=\"c-no\">76</span><span class=\"c-src\">            print(e.delta, end=<span class=\"c-str\">&quot;&quot;</span>, flush=<span class=\"c-kw\">True</span>)</span></div>\n<div class=\"c-line\" data-line=\"77\"><span class=\"c-no\">77</span><span class=\"c-src\">    print()</span></div>\n<div class=\"c-line\" data-line=\"78\"><span class=\"c-no\">78</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"79\"><span class=\"c-no\">79</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"80\"><span class=\"c-no\">80</span><span class=\"c-src\"><span class=\"c-kw\">async</span> <span class=\"c-kw\">def</span> main() -&gt; <span class=\"c-kw\">None</span>:</span></div>\n<div class=\"c-line\" data-line=\"81\"><span class=\"c-no\">81</span><span class=\"c-src\">    kb = <span class=\"c-kw\">await</span> build_kb()</span></div>\n<div class=\"c-line\" data-line=\"82\"><span class=\"c-no\">82</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"83\"><span class=\"c-no\">83</span><span class=\"c-src\">    <span class=\"c-com\"># ---- static 模式:首轮自动检索,HintBlock 一次性注入(模型被动看) ----</span></span></div>\n<div class=\"c-line\" data-line=\"84\"><span class=\"c-no\">84</span><span class=\"c-src\">    static_mw = RAGMiddleware(</span></div>\n<div class=\"c-line\" data-line=\"85\"><span class=\"c-no\">85</span><span class=\"c-src\">        knowledge_bases=[kb],</span></div>\n<div class=\"c-line\" data-line=\"86\"><span class=\"c-no\">86</span><span class=\"c-src\">        parameters=RAGMiddleware.Parameters(mode=<span class=\"c-str\">&quot;static&quot;</span>),</span></div>\n<div class=\"c-line\" data-line=\"87\"><span class=\"c-no\">87</span><span class=\"c-src\">    )</span></div>\n<div class=\"c-line\" data-line=\"88\"><span class=\"c-no\">88</span><span class=\"c-src\">    static_agent = Agent(</span></div>\n<div class=\"c-line\" data-line=\"89\"><span class=\"c-no\">89</span><span class=\"c-src\">        name=<span class=\"c-str\">&quot;static_qa&quot;</span>,</span></div>\n<div class=\"c-line\" data-line=\"90\"><span class=\"c-no\">90</span><span class=\"c-src\">        system_prompt=<span class=\"c-str\">&quot;你是文档问答助手,根据检索到的资料回答。&quot;</span>,</span></div>\n<div class=\"c-line\" data-line=\"91\"><span class=\"c-no\">91</span><span class=\"c-src\">        model=make_model(),</span></div>\n<div class=\"c-line\" data-line=\"92\"><span class=\"c-no\">92</span><span class=\"c-src\">        toolkit=Toolkit(),</span></div>\n<div class=\"c-line\" data-line=\"93\"><span class=\"c-no\">93</span><span class=\"c-src\">        middlewares=[static_mw],</span></div>\n<div class=\"c-line\" data-line=\"94\"><span class=\"c-no\">94</span><span class=\"c-src\">    )</span></div>\n<div class=\"c-line\" data-line=\"95\"><span class=\"c-no\">95</span><span class=\"c-src\">    <span class=\"c-kw\">await</span> run(static_agent, <span class=\"c-str\">&quot;拆封过的商品能退吗?扣多少?&quot;</span>, <span class=\"c-str\">&quot;static 模式(自动注入)&quot;</span>)</span></div>\n<div class=\"c-line\" data-line=\"96\"><span class=\"c-no\">96</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"97\"><span class=\"c-no\">97</span><span class=\"c-src\">    <span class=\"c-com\"># ---- agentic 模式:暴露 search_knowledge 工具,模型主动决定何时搜 ----</span></span></div>\n<div class=\"c-line\" data-line=\"98\"><span class=\"c-no\">98</span><span class=\"c-src\">    agentic_mw = RAGMiddleware(knowledge_bases=[kb])  <span class=\"c-com\"># 默认 agentic</span></span></div>\n<div class=\"c-line\" data-line=\"99\"><span class=\"c-no\">99</span><span class=\"c-src\">    agentic_agent = Agent(</span></div>\n<div class=\"c-line\" data-line=\"100\"><span class=\"c-no\">100</span><span class=\"c-src\">        name=<span class=\"c-str\">&quot;agentic_qa&quot;</span>,</span></div>\n<div class=\"c-line\" data-line=\"101\"><span class=\"c-no\">101</span><span class=\"c-src\">        system_prompt=<span class=\"c-str\">&quot;你是文档问答助手。需要查资料时用 search_knowledge 工具检索后再答。&quot;</span>,</span></div>\n<div class=\"c-line\" data-line=\"102\"><span class=\"c-no\">102</span><span class=\"c-src\">        model=make_model(),</span></div>\n<div class=\"c-line\" data-line=\"103\"><span class=\"c-no\">103</span><span class=\"c-src\">        toolkit=Toolkit(),</span></div>\n<div class=\"c-line\" data-line=\"104\"><span class=\"c-no\">104</span><span class=\"c-src\">        middlewares=[agentic_mw],</span></div>\n<div class=\"c-line\" data-line=\"105\"><span class=\"c-no\">105</span><span class=\"c-src\">    )</span></div>\n<div class=\"c-line\" data-line=\"106\"><span class=\"c-no\">106</span><span class=\"c-src\">    <span class=\"c-kw\">await</span> run(agentic_agent, <span class=\"c-str\">&quot;退款多久到账?&quot;</span>, <span class=\"c-str\">&quot;agentic 模式(主动搜索)&quot;</span>)</span></div>\n<div class=\"c-line\" data-line=\"107\"><span class=\"c-no\">107</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"108\"><span class=\"c-no\">108</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"109\"><span class=\"c-no\">109</span><span class=\"c-src\"><span class=\"c-kw\">if</span> __name__ == <span class=\"c-str\">&quot;__main__&quot;</span>:</span></div>\n<div class=\"c-line\" data-line=\"110\"><span class=\"c-no\">110</span><span class=\"c-src\">    asyncio.run(main())</span></div>\n</div>", "lines": 110, "explanation": "rag_two_modes.py 是本教程的可运行示例代码，示范对应周次核心概念；顶部注释含运行前置依赖与预期输出，建议结合左侧源码与对应周文档「动手作业」一起读。", "knowledge_points": [], "related_docs": ["W08-RAG与多Agent-Team与服务化"]};
